from pathlib import Path
import zipfile,xml.etree.ElementTree as ET,json
from html.parser import HTMLParser
N={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
def book(path):
 z=zipfile.ZipFile(path); ss=[]
 if 'xl/sharedStrings.xml' in z.namelist():
  ss=[''.join(e.itertext()) for e in ET.fromstring(z.read('xl/sharedStrings.xml')).findall('m:si',N)]
 rel={e.attrib['Id']:e.attrib['Target'] for e in ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))}
 out={}
 for s in ET.fromstring(z.read('xl/workbook.xml')).findall('m:sheets/m:sheet',N):
  target=rel[s.attrib['{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id']]; target=target.lstrip('/') if target.startswith('/') else 'xl/'+target
  cells={}
  for c in ET.fromstring(z.read(target)).findall('.//m:sheetData/m:row/m:c',N):
   v=c.find('m:v',N); val=v.text if v is not None else ''.join(c.find('m:is',N).itertext()) if c.find('m:is',N) is not None else None
   if c.attrib.get('t')=='s': val=ss[int(val)]
   elif val is not None and c.attrib.get('t') not in ('str','inlineStr'):
    try: val=float(val); val=int(val) if val.is_integer() else val
    except ValueError: pass
   if val is not None: cells[c.attrib['r']]=val
  out[s.attrib['name']]=cells
 return out
class Text(HTMLParser):
 def __init__(self): super().__init__(); self.lines=[]; self.skip=0; self.links=[]
 def handle_starttag(self,t,a):
  if t in ('script','style'): self.skip+=1
  if t=='a': self.links.append(dict(a))
 def handle_endtag(self,t):
  if t in ('script','style'): self.skip-=1
 def handle_data(self,d):
  if not self.skip and d.strip(): self.lines.append(d.strip())
for f in Path('.').glob('*.xlsx'):
 b=book(f); Path('evidence/'+f.stem+'.json').write_text(json.dumps(b,ensure_ascii=False,indent=2))
 with open('evidence/'+f.stem+'.txt','w') as out:
  for name,cells in b.items():
   if 'kensatsu' in f.name or '沖縄' in name or name in ['47','47沖縄県']:
    out.write('SHEET '+name+'\\n')
    for c,v in cells.items(): out.write(f'{c}\\t{v}\\n')
 print(f,list(b))
for f in Path('.').glob('*.html'):
 p=Text(); p.feed(f.read_text()); Path('evidence/'+f.stem+'.txt').write_text('\\n'.join(p.lines)); Path('evidence/'+f.stem+'_links.json').write_text(json.dumps(p.links,ensure_ascii=False,indent=2))
